      const diff = Math.abs(ag - st);
      if (diff >= 20) {
        if (ag >= 80 && ac >= 80 && h <= 175) {
          type = 1;
        } else if (st >= 80 && ac >= 55 && h >= 188) {
          type = 7;
        }
      } else if (diff >= 12) {
        if (ag >= 70 && ac >= 80 && h <= 182) {
          type = 2;
        } else if (st >= 75 && ac >= 55 && h >= 183) {
          type = 6;
        }
      } else if (diff >= 4) {
        if (ag >= 65 && ac >= 70 && h <= 182) {
          type = 3;
        } else if (st >= 65 && ac >= 40 && h >= 181) {
          type = 5;
        }
      }
      return type;
